import{_ as e,c as r,o as l,ag as a}from"./chunks/framework.BSxiluPM.js";const f=JSON.parse('{"title":"주택임대차계약","description":"","frontmatter":{"title":"주택임대차계약","date":"2026-01-24T00:30:00.000Z","tags":["부동산","임대차계약","월세","최우선변제권","다가구주택","재개발"]},"headers":[],"relativePath":"posts/housing-lease-agreement.md","filePath":"posts/housing-lease-agreement.md","lastUpdated":1769215593000}'),n={name:"posts/housing-lease-agreement.md"};function s(o,t,g,i,d,h){return l(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="주택임대차계약" tabindex="-1">주택임대차계약 <a class="header-anchor" href="#주택임대차계약" aria-label="Permalink to &quot;주택임대차계약&quot;">​</a></h1><p>저는 경기도 역세권 <mark>아파트 청약에 당첨되어 분양권을 보유</mark>하고 있지만 <strong>아파트 입주가 2029년 1월로 예정</strong>되어 있어서 입주 전까지는 약 3년이라는 생각보다 긴 시간이 남아있는 상황이에요. 결혼을 약속하게 된 여자친구와 함께 살아갈 작은 보금자리가 필요한 상황이 되었어요.</p><p>평소 여자친구의 생활권이었던 신대방삼거리역 근처의 투룸 매물을 알아보았으나 투룸 매물을 구경조차 못하는 상황이라 <mark>광명사거리역 근처의 공공재개발 구역 내 신축 다가구주택</mark>의 계약을 앞두고 있습니다. 저는 여자친구와 다르게 부동산 계약 경험이 없었던 입장이라 많이 찾아보고 공부하게 되었는데 매물 확인부터 계약 과정에서 부족했던 점이 있어서 <mark>주택임대차계약</mark>에 대해 정리해보려고 해요.</p><h2 id="_1-매물-정보와-계약-조건" tabindex="-1">1. 매물 정보와 계약 조건 <a class="header-anchor" href="#_1-매물-정보와-계약-조건" aria-label="Permalink to &quot;1. 매물 정보와 계약 조건&quot;">​</a></h2><p>제가 계약하고자 했던 매물은 <strong>광명7R 공공재개발구역</strong> 내에 위치한 신축 다가구주택입니다.</p><ul><li><strong>건물 개요</strong>: 2021년 준공 (내부 컨디션 최상), 주차 가능</li><li><strong>유형</strong>: 다가구주택 (6가구)</li><li><strong>보증금 / 월세</strong>: <strong>5,000만 원 / 약 100만 원</strong></li><li><strong>특이사항</strong>: <ol><li><strong>주인 거주</strong>: 건물주(명의자)가 5층에 실거주</li><li><strong>근저당</strong>: 등기부등본상 토지와 건물이 공동담보로 <strong>채권최고액 6억 원</strong> 설정</li><li><strong>재개발</strong>: 사업시행인가 및 관리처분계획인가 단계 예정</li></ol></li></ul><h2 id="_2-전세보다-준월세" tabindex="-1">2. 전세보다 준월세 <a class="header-anchor" href="#_2-전세보다-준월세" aria-label="Permalink to &quot;2. 전세보다 준월세&quot;">​</a></h2><p><a href="https://n.news.naver.com/article/366/0001137337" target="_blank" rel="noreferrer">전세는 없고, 월세는 비싸고… 서울 임대차 55%는 ‘준월세’</a>라는 뉴스처럼 준월세 매물의 비중이 커지고 있어요. 계약하려는 집도 서울 지역은 아니지만 보증금 5,000만원에 월세(차임) 100만원, 관리비 10만원으로 생각보다 월 주거비가 높았어요. 애초에 저희가 준월세를 고려한 이유는 전세 보증금을 가지고 있어도 향후 신축 아파트를 입주하려는 시기에 자금 흐름이 애매해질 수 있겠다는 우려사항 때문이었어요.</p><blockquote><p>여자친구의 지인이 전세사기를 당했던 경험이 있어서 그에 대한 걱정도 일부 있습니다.</p></blockquote><ul><li>현금 흐름 확보</li><li>다가구주택의 위험성</li></ul><p>가계약 단계에서는 몰랐으나 <strong>임대차계약에서 다가구주택은 굉장히 위험한 매물</strong>이라고 해요. 다세대주택과는 다르게 1인 소유이면서 다른 세입자에 대한 선순위 보증금 현황을 알 수 없다는 구조적인 문제가 있어요. 저희는 다행히도 전세보다는 <strong>최우선변제</strong>를 고려한 월세 계약을 고려하고 있었기 때문에 가계약 당시에는 크게 신경쓰지는 않았던 것 같아요.</p><h2 id="_3-최우선변제권" tabindex="-1">3. 최우선변제권 <a class="header-anchor" href="#_3-최우선변제권" aria-label="Permalink to &quot;3. 최우선변제권&quot;">​</a></h2><p>최우선변제권은 주택임대차보호법에 의거 보증금이 일정금액 이하인 소액임차인에 해당되면 주택이 경매에 넘어가도 선순위 채권인 근저당보다 우선하여 변제받을 수 있는 권리에요. 전입신고로 대항력을 가지게 되면 <mark>근저당 설정일 기준</mark> 최우선변제 금액한도 만큼 먼저 배당받을 수 있어요.</p><p>최우선변제 금액에서 가장 중요한 건 계약 시점이 아니라 해당 주택의 근저당 설정일이에요. 이 건물의 근저당 설정일은 <mark>2022년 3월</mark>로 나와있어서 당시 시행 중이던 법령을 따라야 해요.</p><h3 id="광명시-최우선변제-기준-2022-03-근저당-기준" tabindex="-1">광명시 최우선변제 기준 (2022.03 근저당 기준) <a class="header-anchor" href="#광명시-최우선변제-기준-2022-03-근저당-기준" aria-label="Permalink to &quot;광명시 최우선변제 기준 (2022.03 근저당 기준)&quot;">​</a></h3><p>광명시는 당시에도 <strong>과밀억제권역</strong>에 해당합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">소액임차인 인정 범위 (보증금)</th><th style="text-align:left;">최우선변제금 (보장 금액)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>과밀억제권역</strong></td><td style="text-align:left;"><strong>1억 3,000만 원 이하</strong></td><td style="text-align:left;"><strong>최대 4,300만 원</strong></td></tr></tbody></table><p><strong>분석 결과</strong>:</p><ul><li>저의 보증금은 <strong>5,000만 원</strong>이므로 <strong>1억 3,000만 원 이하</strong> 조건에 부합 (<strong>소액임차인</strong> 해당)</li><li>선순위채권(근저당)보다 먼저 <strong>4,300만원</strong> <mark>최우선변제 가능</mark></li><li>선순위 보증금으로 인한 <strong>700만원</strong> <mark>손실 위험</mark></li></ul><p>주택 임대차에서 최우선변제는 월세를 제외하고 보증금만으로 판단해요. 가계약 당시에 고려하지 못한 건 원래 서울 지역의 매물을 찾고있었기에 보증금 전액이 보호될 줄 알았던 거엿죠. 하지만, 가계약 이후에 확인해본결과 <mark>근저당 설정일 기준으로 4,300만원까지 보호</mark>되고 700만원은 보호받지 못한다는 사실을 알게 되었어요. 따라서, 최우선변제 금액을 제외한 나머지는 받지 못한다는 것을 가정해야해요.</p><h3 id="다가구주택의-경매-시나리오" tabindex="-1">다가구주택의 경매 시나리오 <a class="header-anchor" href="#다가구주택의-경매-시나리오" aria-label="Permalink to &quot;다가구주택의 경매 시나리오&quot;">​</a></h3><p>최악의 상황을 가정한다면 최우선변제 금액보다 낙찰가가 낮아서 <mark>최우선변제금이 전액 보장되지 않을 가능성도 있다</mark>는 거겠죠. 주택임대차보호법에 따라 <strong>최우선변제금의 합계액은 주택가액(경매 낙찰가)의 2분의 1을 초과할 수 없습니다.</strong> 즉, 낙찰가의 <strong>2분의 1</strong>을 소액임차인들이 나누어 배당(<strong>안분배당</strong>)을 받게 됩니다.</p><h2 id="_4-확정일자-보유현황" tabindex="-1">4. 확정일자 보유현황 <a class="header-anchor" href="#_4-확정일자-보유현황" aria-label="Permalink to &quot;4. 확정일자 보유현황&quot;">​</a></h2><p>다가구주택에서 선순위 세입자 보증금을 알기 위해서는 <mark>확정일자 보유현황</mark> 을 임대인에게 요청해야해요. 임대인 동의 없이 임차인이 확정일자 보유현황을 조회하려면 반드시 임대차계약서 사본이 필요하거든요. 따라서, 사전에 임대인에게 요청해서 임대인이 제공하지 않으면 안전한 다가구주택에 해당되는지 알기 어려워요.</p><p>특히 최근 판례와 언론 보도에 따르면 <a href="https://v.daum.net/v/20260122060142008" target="_blank" rel="noreferrer">다가구주택에 대한 중개인의 선순위 보증금 설명 의무</a>가 강화되고 있습니다. 공인중개사는 임대인에게 관련 자료(확정일자 부여현황 등)를 요구하여 임차인에게 확인시켜줄 의무가 있으므로, 계약 전 적극적으로 이를 요구해야 합니다.</p><p>저는 가계약된 다가구 주택의 선순위 보증금 및 전세 세입자 현황을 확인하고자 중개보조원을 통해 임대인에게 확정일자 보유현황을 요청했습니다. 월세 계약이어도 확정일자 보유현황을 확인하는 이유는 단순히 선순위 보증금 총액을 아는 것을 넘어 <strong>나와 같은 소액임차인 현황을 파악</strong>해야 하기 때문이에요. 확정일자 현황 서류에는 &#39;소액임차인 여부&#39;가 별도로 기재되지 않으므로, 제가 직접 <strong>근저당 설정일(2022.03) 기준으로 보증금이 1억 3,000만 원 이하인 세대</strong>를 파악해두어야 합니다.</p><h2 id="_5-월세보증보험" tabindex="-1">5. 월세보증보험 <a class="header-anchor" href="#_5-월세보증보험" aria-label="Permalink to &quot;5. 월세보증보험&quot;">​</a></h2><p>해당 매물은 <strong>사업시행인가 단계를 앞두고 있는 재개발 구역</strong>에 위치해 있기 때문에, <strong>최우선변제에 해당되는 월세 계약임에도</strong> 혹시 모를 상황에 대비하여 보증금 반환에 대한 위험성을 최소화하고자 보증보험 가입을 알아보니 전세 뿐만 아니라 월세 보증금에 대해서도 보증보험에 가입할 순 있다고 하더라도 다가구주택은 보증보험 가입이 현실적으로 매우 어려운 구조라고 해요.</p><h3 id="다가구주택의-개별단독주택가격" tabindex="-1">다가구주택의 개별단독주택가격 <a class="header-anchor" href="#다가구주택의-개별단독주택가격" aria-label="Permalink to &quot;다가구주택의 개별단독주택가격&quot;">​</a></h3><p>중개인과 함께 매물을 확인하러 갔을때는 중개사무소에서 생각하는 감정평가액은 <strong>24억~28억 원</strong>으로 안전한 매물이라고 생각했어요. 하지만, 보증보험 가입 가능 여부를 확인하기 위해서 공시된 <a href="https://www.realtyprice.kr/notice/hpindividual/search.htm" target="_blank" rel="noreferrer">개별단독주택가격</a>을 확인해보니 <strong>6억 8,400만 원(2025년 기준)</strong> 에 불과했어요.</p><p>다가구주택은 아파트와 달리 KB시세나 한국부동산원 시세가 없기 때문에, 보증기관에서는 <strong>공시된 개별단독주택가격</strong>을 기준으로 주택가격을 산정하게 되는데요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">주택가격 산정 기준 (다가구주택)</th><th style="text-align:left;">주택가격 (<strong>6.84억</strong> 기준)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>HUG</strong> (주택도시보증공사)</td><td style="text-align:left;">개별단독주택가격 × <strong>140%</strong></td><td style="text-align:left;"><strong>9억 5,760만 원</strong></td></tr><tr><td style="text-align:left;"><strong>SGI</strong> (서울보증보험)</td><td style="text-align:left;">개별단독주택가격 × <strong>130%</strong></td><td style="text-align:left;"><strong>8억 8,920만 원</strong></td></tr></tbody></table><p>이처럼 공시가격에 일정 비율을 반영하더라도 감정평가액과는 괴리가 매우 큽니다.</p><h3 id="가입-심사-기준" tabindex="-1">가입 심사 기준 <a class="header-anchor" href="#가입-심사-기준" aria-label="Permalink to &quot;가입 심사 기준&quot;">​</a></h3><p>보증보험 가입을 위해서는 <strong>보증한도(주택가격 × 담보인정비율 90% - 선순위채권 등)</strong> 내에 전세보증금이 들어와야 합니다. 또한, 다음과 같은 까다로운 조건들을 모두 충족해야 합니다.</p><ol><li><strong>선순위채권(근저당)이 주택가액의 60% 이내</strong>일 것</li><li><strong>주택의 건물과 토지(대지권)가 모두 임대인의 소유</strong>일 것</li><li><strong>선순위채권 + 선순위 보증금액 합계가 주택가액의 80% 이내</strong>일 것 <ul><li>선순위 보증금액에는 후순위 및 공실의 최우선변제금도 포함</li><li>주택가액 = 주택가격 × 담보인정비율(90%)</li></ul></li><li><strong>타 전세계약체결내역 확인서(공사양식) 상 가구수와 건축물대장 상 가구수가 일치</strong>할 것</li></ol><p>여기서 중요한 부분은 <strong>선순위채권</strong>은 등기부등본의 근저당 채권최고액 뿐만 아니라 나보다 먼저 전입하고 있는 다른 세입자들의 선순위 보증금의 합계를 모두 포함해야한다는 점이에요.</p><p>해당 건물의 경우 <strong>HUG 기준 주택가격은 9억 5,760만 원</strong>입니다. 여기에 담보인정비율 90%를 곱한 <strong>주택가액은 약 8억 6,184만 원</strong>입니다. 이를 토대로 심사 기준을 대입해보면 다음과 같이 모든 조건에서 탈락하게 됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">기준 한도</th><th style="text-align:left;">실제 해당 금액</th><th style="text-align:left;">결과</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>선순위채권 60%</strong></td><td style="text-align:left;"><strong>5억 1,710만 원</strong> (주택가액의 60%)</td><td style="text-align:left;">6억원</td><td style="text-align:left;"><strong>부적격</strong></td></tr><tr><td style="text-align:left;"><strong>부채비율 80%</strong></td><td style="text-align:left;"><strong>6억 8,947만 원</strong> (주택가액의 80%)</td><td style="text-align:left;">11억 2천만원</td><td style="text-align:left;"><strong>부적격</strong></td></tr></tbody></table><p>주택도시보증공사에서 제공하는 <a href="https://khig.khug.or.kr/websquare/popup.html?w2xPath=/cg/ae/CGAE034P02.xml" target="_blank" rel="noreferrer">보증가능여부 간편확인</a> 서비스를 이용했을 때 <strong>가입 불가</strong> 판정이 나오므로 HUG 보증보험 가입은 불가능합니다.</p><h3 id="sgi서울보증-이라면" tabindex="-1">SGI서울보증 이라면? <a class="header-anchor" href="#sgi서울보증-이라면" aria-label="Permalink to &quot;SGI서울보증 이라면?&quot;">​</a></h3><p>SGI의 주택담보대출비율(LTV) 계산식은 <code>(임차보증금 + 선순위채권 등) ÷ 주택가격</code> 입니다.</p><ul><li><strong>담보설정액</strong>: 내 보증금(5천) + 근저당(6억) + 선순위보증금(5.2억) = <strong>11억 7,000만 원</strong></li><li><strong>주택가격</strong>: 개별단독주택가격(6.84억) × 130% = <strong>8억 8,920만 원</strong></li></ul><p>계산 결과 <strong>LTV가 약 131.5%</strong> 로 가입 기준인 <strong>100% 이내</strong>를 초과하여 가입이 불가능합니다. 다만, 개별단독주택가격 대신 <strong>공인중개사 시세 확인서</strong>를 제출하여 주택가격을 시세에 가깝게 인정받을 수도 있겠지만, 이 역시 임대인의 적극적인 서류 협조가 없으면 불가능합니다.</p><h3 id="보증보험-가입을-위한-임대인의-협조" tabindex="-1">보증보험 가입을 위한 임대인의 협조 <a class="header-anchor" href="#보증보험-가입을-위한-임대인의-협조" aria-label="Permalink to &quot;보증보험 가입을 위한 임대인의 협조&quot;">​</a></h3><p>주택가격 기준에 해당되더라도 <strong>다가구주택의 경우 임대인의 서류 협조가 필수적</strong>입니다. 보증회사별로 다음의 서류들을 임대인에게 요청해야 하거든요.</p><ul><li><strong>HUG</strong>: 타전세계약체결내역확인서, 확정일자부여현황</li><li><strong>SGI서울보증</strong>: 임대차사실확인서, 전입세대열람원, 확정일자부여현황</li></ul><p>즉, 임대인의 협조가 없다면 보증보험 가입은 애초에 불가능합니다. 따라서, <strong>보증보험 가입을 위한 임대인의 협조를 특약으로 넣을 필요가 없고</strong> 본 계약 시 구두로 전달받은 선순위 보증금이 맞는지 <mark>확정일자 부여현황</mark>을 확인해보는 것으로 갈무리하려 합니다.</p><h2 id="_6-계약-시-확인사항" tabindex="-1">6. 계약 시 확인사항 <a class="header-anchor" href="#_6-계약-시-확인사항" aria-label="Permalink to &quot;6. 계약 시 확인사항&quot;">​</a></h2><p>계약 당일, 다음의 서류들을 반드시 발급받아 확인해야 합니다.</p><ol><li><strong>등기부등본 (건물 + 토지)</strong>: 소유자 및 근저당 설정 내역 확인 (계약금 입금 직전 발급분)</li><li><strong>건축물대장</strong>: 위반건축물 등재 여부 및 호수 일치 여부</li><li><strong>확정일자 부여현황</strong>: 선순위 임차인 보증금 및 소액임차인 현황 재확인</li><li><strong>납세증명서 (국세) &amp; 지방세 납세증명서</strong>: 임대인의 세금 체납 여부 확인</li></ol><p>부동산 계약에서 <strong>건축물대장</strong>과 <strong>등기부등본</strong>은 법적으로 임차인을 보호해주지 않는다고 해요. 그래서 대부분 임차인이 보호받고자 하는 부분은 <strong>특약 사항</strong>으로 명시해야 한다고 합니다.</p><h3 id="특약-사항" tabindex="-1">특약 사항 <a class="header-anchor" href="#특약-사항" aria-label="Permalink to &quot;특약 사항&quot;">​</a></h3><ul><li>임대인은 현 등기부등본 상태를 임차인이 대항력을 갖추게 되는 날의 다음 영업일까지 유지하기로 한다.</li><li>재개발 사업의 관리처분계획 인가, 이주 통지로 인하여 임차인에게 이주 또는 명도가 요구될 경우, 임차인은 2개월 내로 이에 적극 협조하되, 임대인은 통상적인 이사비용을 부담한다.</li></ul><p>마지막 특약 사항의 경우 계약기간 내 퇴거가 이루어질 가능성은 낮으나 임차인 입장에서는 넣어두는게 좋을 것 같아 요청은 해보아야할 것 같네요.</p><h2 id="_7-주택-임대차계약-신고" tabindex="-1">7. 주택 임대차계약 신고 <a class="header-anchor" href="#_7-주택-임대차계약-신고" aria-label="Permalink to &quot;7. 주택 임대차계약 신고&quot;">​</a></h2><p>2025년 6월부터 <mark>보증금 6천만원 또는 월차임 30만원 초과</mark>에 대한 <a href="https://www.youtube.com/watch?v=veiXWtt2IWQ" target="_blank" rel="noreferrer">주택 임대차계약 신고가 의무화</a>되었어요. 가계약금 입금 시 중개법인을 통해 계약에 대한 내용을 명시하였기 때문에 <a href="https://youtu.be/FAN6ECKzo3M?si=xMcuvfh_voPuBD__" target="_blank" rel="noreferrer">가계약 입금일 기준으로 계약 체결일</a>로 간주하여 신고해야 한다고 해요.</p><p>저의 일정은 다음과 같습니다.</p><ul><li><strong>가계약</strong>: 1월 17일</li><li><strong>본계약</strong>: 1월 31일</li><li><strong>입주예정</strong>: 3월 6일</li></ul><p>따라서, 가계약 시점부터 입주일자 까지는 30일을 초과하기 때문에 임대차계약 후 바로 신고해야 합니다.</p><h2 id="_8-입주-준비" tabindex="-1">8. 입주 준비 <a class="header-anchor" href="#_8-입주-준비" aria-label="Permalink to &quot;8. 입주 준비&quot;">​</a></h2><p>입주 전후로 반드시 챙겨야 할 사항들을 정리했습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">할 일</th><th style="text-align:left;">시기</th><th style="text-align:left;">참고사항</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>입주청소</strong></td><td style="text-align:left;">셀프 청소 진행</td><td style="text-align:left;">이사 당일부터 2일간</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>도시가스</strong></td><td style="text-align:left;">전입 신청 및 기사 방문 예약</td><td style="text-align:left;">입주 2~3일 전</td><td style="text-align:left;"><strong>삼천리도시가스</strong> 사전 예약 필수</td></tr><tr><td style="text-align:left;"><strong>전기</strong></td><td style="text-align:left;">전입 신청 (명의 변경)</td><td style="text-align:left;">입주 당일</td><td style="text-align:left;"><strong>한전ON</strong> 온라인 신청</td></tr><tr><td style="text-align:left;"><strong>수도</strong></td><td style="text-align:left;">전입 신청 (명의 변경)</td><td style="text-align:left;">입주 당일</td><td style="text-align:left;"><strong>광명시청 수도과</strong></td></tr><tr><td style="text-align:left;"><strong>전입신고</strong></td><td style="text-align:left;">정부24</td><td style="text-align:left;"><strong>입주 당일 즉시</strong></td><td style="text-align:left;"><mark>대항력 확보</mark></td></tr><tr><td style="text-align:left;"><strong>주소변경</strong></td><td style="text-align:left;">우편물 주소 이전</td><td style="text-align:left;">입주 후</td><td style="text-align:left;">금융, 통신사 등</td></tr></tbody></table>',63)])])}const x=e(n,[["render",s]]);export{f as __pageData,x as default};
